-- Rebrand: Digitals Minds -> WEDOSELL (owner's instruction, 2026-11-25).
--
-- Renames the institute in content shown to visitors, students and staff. Text replacement
-- only: no rows or columns are deleted, and ids, relations, enrollments, payments and
-- history are untouched. Deliberately NOT changed (records of what people actually wrote or
-- what happened): AuditLog, SupportMessage, Inquiry, InquiryNote, Testimonial quotes,
-- Certificate snapshots and User names. The domain digitalsminds.com and its email
-- addresses are operational and stay until a replacement is provided.

UPDATE `SiteSetting` SET `value` = REPLACE(REPLACE(REPLACE(REPLACE(`value`, 'Digitals Minds', 'WEDOSELL'), 'DIGITALS MINDS', 'WEDOSELL'), 'Digital Minds', 'WEDOSELL'), 'Learn | Grow | Earn', 'E-commerce & Business Growth')
WHERE `value` LIKE '%Digital% Minds%' OR `value` LIKE '%Learn | Grow | Earn%';

