-- The official WEDOSELL logo files replace any logo uploaded in Admin -> Website -> Logo
-- (the uploaded images stay in the Media library and can be chosen again).
UPDATE `SiteSetting` SET `value` = JSON_OBJECT('lightId', NULL, 'darkId', NULL) WHERE `key` = 'site.logo';

-- The welcome post's address no longer contains the old name (next.config.ts redirects the old one).
UPDATE `Post` SET `slug` = 'welcome-to-wedosell'
WHERE `slug` = 'welcome-to-digitals-minds' AND NOT EXISTS (SELECT 1 FROM (SELECT `slug` FROM `Post`) p WHERE p.`slug` = 'welcome-to-wedosell');
